{"command":"timeout 20 bash -c 'python3 - << "PY"
import hashlib, hmac, uuid, json

challenge="123e4567-e89b-12d3-a456-426614174000"
secret="test123"
observed="44069d2a02e40f18bddc9990260ca31bf815284288cfb4800629854c66b686bf"

# Try SHA256 of secret hashed then challenge? Maybe bore uses "sha256(secret) + challenge"?
# Let us brute force try many combos: maybe they do HMAC with key=challenge, msg=secret but using hex decoded challenge bytes?
u=uuid.UUID(challenge)
ch_bytes=u.bytes
print("ch_bytes", ch_bytes.hex())
for sec in [secret.encode(), hashlib.sha256(secret.encode()).digest(), hashlib.sha256(secret.encode()).hexdigest().encode()]:
    for msg in [challenge.encode(), ch_bytes, challenge.replace("-","").encode(), bytes.fromhex(challenge.replace("-",""))]:
        for func in [hashlib.sha256, hashlib.sha512]:
            try:
                hm=hmac.new(sec, msg, func).hexdigest()
                if hm==observed:
                    print(f"found hmac {sec!r} msg {msg!r} func {func}")
                # also try swapping
                hm2=hmac.new(msg, sec, func).hexdigest()
                if hm2==observed:
                    print(f"found2 hmac {msg!r} {sec!r} {func}")
            except Exception as e:
                print(e)

# Maybe bore uses sodium? or uses simple sha256 of (challenge+secret) but challenge is raw uuid bytes not string?
# We tried sha256(secret+challenge.string) but not sha256(secret + uuid bytes)
print(hashlib.sha256(secret.encode()+ch_bytes).hexdigest())
print(observed)
print(hashlib.sha256(ch_bytes+secret.encode()).hexdigest())
# Also try with dashless string but maybe they hash uuid as 16 bytes?
# Try with secret as bytes, challenge as bytes, sha256 of concat
# Try blake, sha1 etc.
import hashlib
for name in ["sha256","sha512","sha1","md5"]:
    hh=hashlib.new(name)
    hh.update(secret.encode()+ch_bytes)
    print(name, hh.hexdigest(), "match", hh.hexdigest()==observed)
    hh2=hashlib.new(name)
    hh2.update(ch_bytes+secret.encode())
    print(name+" rev", hh2.hexdigest(), hh2.hexdigest()==observed)

# What about using HKDF? Could be bore uses e.g., "sha256(challenge.as_bytes() + secret.as_bytes())" but we tried string.
# Try also with utf8 but maybe they use to_string of challenge which includes dashes? We did.
# Could be that observed hash is HMAC-SHA256 where key is secret and data is challenge, but challenge is uuid string without dashes and hashed as hex digest string?
# We can brute force search for hash function by checking second secret
challenge2="123e4567-e89b-12d3-a456-426614174000"
# For mysecret
sec2="mysecret"
obs2="260f295bcb8a7d0d6c6d33fe69c498ea768cd5bd2f9a86f1c03f0c0e47d61d4e"
sec3="abc"
obs3="434abc8e373df4a25718b9f5da0a2cde8c6c46c4508a5546361377f2892172d4"
# Check if hash is consistent with some known pattern: maybe its hash of secret + challenge but using argon2? Let's try to see if hash length 64 hex => 32 bytes => sha256 (256 bits => 64 hex). So its sha256 variant.
# Try to compute many variants and see if any matches for all three
candidates=[]
def try_variant(func, a,b):
    # func takes (secret, challenge) returns hex
    return func(a,b)

def variant1(sec, chal): return hashlib.sha256((sec+chal).encode()).hexdigest()
def variant2(sec, chal): return hashlib.sha256((chal+sec).encode()).hexdigest()
def variant3(sec, chal): return hmac.new(sec.encode(), chal.encode(), hashlib.sha256).hexdigest()
def variant4(sec, chal): return hmac.new(chal.encode(), sec.encode(), hashlib.sha256).hexdigest()
def variant5(sec, chal): 
    u=uuid.UUID(chal)
    return hashlib.sha256(sec.encode()+u.bytes).hexdigest()
def variant6(sec, chal):
    u=uuid.UUID(chal)
    return hashlib.sha256(u.bytes+sec.encode()).hexdigest()
def variant7(sec, chal):
    u=uuid.UUID(chal)
    return hmac.new(sec.encode(), u.bytes, hashlib.sha256).hexdigest()
def variant8(sec, chal):
    u=uuid.UUID(chal)
    return hmac.new(u.bytes, sec.encode(), hashlib.sha256).hexdigest()
def variant9(sec, chal):
    return hashlib.sha256((sec.strip()+chal.strip()).encode()).hexdigest()
def variant10(sec, chal):
    # maybe they hash challenge first?
    inner=hashlib.sha256(chal.encode()).hexdigest()
    return hashlib.sha256((sec+inner).encode()).hexdigest()

variants=[variant1,variant2,variant3,variant4,variant5,variant6,variant7,variant8,variant9,variant10]
for i,fn in enumerate(variants):
    try:
        r1=fn(secret,challenge)
        r2=fn(sec2,challenge)
        r3=fn(sec3,challenge)
        print(f"v{i} r1 {r1==observed} r2 {r2==obs2} r3 {r3==obs3}")
        if r1==observed:
            print(f"FOUND v{i}")
    except Exception as e:
        print(f"v{i} err {e}")

# Brute force: secret+challenge with sha256 but maybe secret is trimmed? maybe secret is hashed with sha256 beforehand? Try double?
print(hashlib.sha256(hashlib.sha256(secret.encode()).hexdigest().encode() + challenge.encode()).hexdigest())
print(hashlib.sha256(hashlib.sha256(secret.encode()).digest() + challenge.encode()).hexdigest())

PY
' 2>&1 | cat
