{"command":"cat /proc/net/tcp | head -n 20
python3 - << 'PY'
import os, signal, subprocess as sp, time, socket
# Try to kill by finding listening pid again
with open("/proc/net/tcp") as f:
    for line in f:
        if "0A" in line:
            parts=line.split()
            inode=parts[9]
            print(f"listener inode {inode} {line.strip()}")
            # search
            for pid in os.listdir("/proc"):
                if pid.isdigit():
                    try:
                        for fd in os.listdir(f"/proc/{pid}/fd"):
                            try:
                                link=os.readlink(f"/proc/{pid}/fd/{fd}")
                                if inode in link:
                                    print(f" holder pid {pid} fd {fd} link {link}")
                                    try:
                                        print(open(f"/proc/{pid}/cmdline","rb").read())
                                    except: pass
                            except: pass
                    except: pass
# Now try to connect and see if server still there
for addr in [("127.0.0.1",7835)]:
    s=socket.socket()
    s.settimeout(0.5)
    try:
        s.connect(addr)
        print(f"still listening {addr}")
        s.close()
    except Exception as e:
        print(f"not listening {addr} {e}")

# The remaining listener after our kills: check ps
print(sp.run(["ps","aux"], capture_output=True, text=True).stdout[:5000])
PY
"}

