async fn write_msg(stream: &mut TcpStream, value: &Value) -> Result<()> {
    let s = serde_json::to_string(value).unwrap();
    stream.write_all(s.as_bytes()).await?;
    stream.write_all(b"\x00").await?;
    stream.flush().await?;
    Ok(())
}

async fn read_msg(stream: &mut TcpStream) -> Result<Value> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        let n = stream.read(&mut byte).await?;
        if n == 0 {
            return Err(anyhow!("unexpected EOF"));
        }
        if byte[0] == 0 {
            break;
        }
        buf.push(byte[0]);
        if buf.len() > 8192 {
            return Err(anyhow!("frame error, invalid byte length"));
        }
    }
    if buf.is_empty() {
        return Err(anyhow!("unexpected EOF"));
    }
    let s = String::from_utf8(buf).context("invalid utf8")?;
    let v: Value = serde_json::from_str(&s).context("unable to parse message")?;
    Ok(v)
}

fn compute_auth(secret: &str, challenge: &str) -> String {
    let key = Sha256::digest(secret.as_bytes());
    let uuid = Uuid::parse_str(challenge).unwrap();
    let mut mac = HmacSha256::new_from_slice(&key).unwrap();
    mac.update(uuid.as_bytes());
    let result = mac.finalize().into_bytes();
    hex::encode(result)
}

