async fn run_local(args: LocalArgs) -> Result<()> {
    // Validate to not empty? It's required by clap, but if empty we still try to connect and will get lookup error
    let server_addr = format!("{}:7835", args.to);
    let mut stream = match timeout(Duration::from_secs(5), TcpStream::connect(&server_addr)).await {
        Ok(Ok(s)) => s,
        Ok(Err(e)) => {
            return Err(anyhow!(e).context(format!("could not connect to {}", server_addr)));
        }
        Err(_) => {
            return Err(anyhow!("timed out").context(format!("could not connect to {}", server_addr)));
        }
    };

    // Handshake
    if let Some(secret) = &args.secret {
        // Expect Challenge
        let msg = timeout(Duration::from_secs(3), read_msg(&mut stream)).await
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?
            .context("failed to read challenge")?;
        if let Some(challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            let auth = compute_auth(secret, challenge);
            write_msg(&mut stream, &json!({"Authenticate": auth})).await?;
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            return Err(anyhow!("server error: {}", err));
        } else {
            // Unexpected, expected Challenge
            return Err(anyhow!("expected authentication challenge, but no secret was required"));
        }
        // Now send Hello
        write_msg(&mut stream, &json!({"Hello": args.port})).await?;
    } else {
        // No secret, send Hello directly
        write_msg(&mut stream, &json!({"Hello": args.port})).await?;
        // Wait for response, could be Challenge (if server requires auth), Hello, or Error
        let msg = timeout(Duration::from_secs(3), read_msg(&mut stream)).await
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?
            .context("failed to read hello response")?;
        if let Some(challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            // Server requires auth but we have no secret
            return Err(anyhow!("server requires authentication, but no client secret was provided"));
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            // Check specific errors
            if err.contains("invalid secret") {
                return Err(anyhow!("server error: invalid secret"));
            } else if err.contains("client port number not in allowed range") {
                return Err(anyhow!("server error: client port number not in allowed range"));
            } else if err.contains("failed to find") {
                return Err(anyhow!("server error: failed to find an available port"));
            } else if err.contains("server requires secret") {
                return Err(anyhow!("server requires authentication, but no client secret was provided"));
            } else {
                return Err(anyhow!("server error: {}", err));
            }
        } else if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
            // Success, but we need to handle Heartbeat that follows
            let allocated = hello_port as u16;
            print_client_connected(allocated);
            print_client_listening(&args.to, allocated);
            // Try to read Heartbeat (may be next message)
            // We should not block forever; try to read with short timeout and ignore
            // The server sends Heartbeat immediately after Hello, so we can try to read it
            // But we already consumed Hello, next read may be Heartbeat. We'll attempt to read with timeout 200ms
            let _ = timeout(Duration::from_millis(200), read_msg(&mut stream)).await;
            // Now enter proxy loop
            return handle_client_control(stream, args).await;
        } else if msg.is_string() && msg.as_str() == Some("Heartbeat") {
            // Unexpected heartbeat before hello?
            return Err(anyhow!("unexpected message"));
        } else {
            return Err(anyhow!("unexpected message: {:?}", msg));
        }
        // For no-secret case, we already handled Hello success above, but we returned. For secret case we continue:
    }

    // For secret case, after sending Hello, wait for Hello response
    if args.secret.is_some() {
        let msg = timeout(Duration::from_secs(3), read_msg(&mut stream)).await
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?
            .context("failed to read hello response")?;
        if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            if err.contains("invalid secret") {
                return Err(anyhow!("server error: invalid secret"));
            } else if err.contains("client port number not in allowed range") {
                return Err(anyhow!("server error: client port number not in allowed range"));
            } else if err.contains("failed to find") {
                return Err(anyhow!("server error: failed to find an available port"));
            } else {
                return Err(anyhow!("server error: {}", err));
            }
        } else if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
            let allocated = hello_port as u16;
            print_client_connected(allocated);
            print_client_listening(&args.to, allocated);
            // Consume heartbeat if present
            let _ = timeout(Duration::from_millis(200), read_msg(&mut stream)).await;
            return handle_client_control(stream, args).await;
        } else {
            return Err(anyhow!("unexpected message: {:?}", msg));
        }
    }

    Ok(())
}

async fn handle_client_control(mut control: TcpStream, args: LocalArgs) -> Result<()> {
    // Loop reading Connection messages
    loop {
        let msg = match read_msg(&mut control).await {
            Ok(m) => m,
            Err(e) => {
                if e.to_string().contains("unexpected EOF") {
                    return Ok(());
                }
                // Connection reset etc.
                return Err(anyhow!(e).context("frame error, invalid byte length"));
            }
        };
        if let Some(conn_id) = msg.get("Connection").and_then(|v| v.as_str()) {
            let conn_id = conn_id.to_string();
            let local_host = args.local_host.clone();
            let local_port = args.local_port;
            let to = args.to.clone();
            let secret = args.secret.clone();
            tokio::spawn(async move {
                if let Err(e) = handle_proxy(conn_id.clone(), local_host, local_port, to, secret).await {
                    // Log proxy error? For now ignore
                    // eprintln!("proxy error: {:#}", e);
                }
            });
        } else if msg.is_string() && msg.as_str() == Some("Heartbeat") {
            // Respond with Heartbeat?
            // Send back Heartbeat
            let _ = write_msg(&mut control, &Value::String("Heartbeat".to_string())).await;
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            eprintln!("server error: {}", err);
            return Err(anyhow!("server error: {}", err));
        } else {
            // Unknown, ignore
        }
    }
}

async fn handle_proxy(conn_id: String, local_host: String, local_port: u16, to: String, secret: Option<String>) -> Result<()> {
    print_proxy_new_connection(&conn_id);
    let server_addr = format!("{}:7835", to);
    let mut stream = TcpStream::connect(&server_addr).await.context(format!("could not connect to {}", server_addr))?;

    if let Some(secret) = &secret {
        // Expect Challenge
        let msg = timeout(Duration::from_secs(3), read_msg(&mut stream)).await
            .map_err(|_| anyhow!("timed out waiting for initial message"))?
            .context("failed to read challenge")?;
        if let Some(challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            let auth = compute_auth(secret, challenge);
            write_msg(&mut stream, &json!({"Authenticate": auth})).await?;
        } else {
            return Err(anyhow!("expected challenge"));
        }
    }
    // Send Accept
    write_msg(&mut stream, &json!({"Accept": conn_id.clone()})).await?;

    // Connect to local
    let local_addr = format!("{}:{}", local_host, local_port);
    let mut local_stream = match TcpStream::connect(&local_addr).await {
        Ok(s) => s,
        Err(e) => {
            print_proxy_exited(&conn_id);
            return Err(anyhow!(e).context(format!("could not connect to local {}", local_addr)));
        }
    };

    // Bidirectional copy
    let result = tokio::io::copy_bidirectional(&mut stream, &mut local_stream).await;
    print_proxy_exited(&conn_id);
    match result {
        Ok(_) => Ok(()),
        Err(e) => Err(anyhow!(e)),
    }
}

async fn run_server(args: ServerArgs) -> Result<()> {
    // Validate bind_addr and bind_tunnels
    let bind_addr: IpAddr = args.bind_addr.parse().map_err(|_| anyhow!("invalid IP address syntax"))?;
    let bind_tunnels: IpAddr = if let Some(s) = &args.bind_tunnels {
        s.parse().map_err(|_| anyhow!("invalid IP address syntax"))?
    } else {
        bind_addr.clone()
    };

    // Validate port range
    if args.min_port > args.max_port {
        return Err(anyhow!("port range is empty"));
    }

    // Bind control listener
    let listener = TcpListener::bind((bind_addr, 7835)).await.map_err(|e| anyhow!(e))?;
    print_server_listening(&bind_addr.to_string());

    // Shared state
    let state = Arc::new(ServerState {
        secret: args.secret.clone(),
        min_port: args.min_port,
        max_port: args.max_port,
        bind_tunnels,
        allocated: AsyncMutex::new(HashMap::new()),
        pending: AsyncMutex::new(HashMap::new()),
        controls: AsyncMutex::new(HashMap::new()),
    });

    loop {
        let (socket, addr) = listener.accept().await?;
        let state = state.clone();
        let peer = addr.to_string();
        tokio::spawn(async move {
            if let Err(e) = handle_server_connection(socket, peer.clone(), state).await {
                // Log error as warn? For handshake failures, we log warn
                // Use print_server_control_warn
                // But we need to know if it's handshake failure
                // For now, just log
                // eprintln!("handle error: {:#}", e);
            }
        });
    }
}

struct ServerState {
    secret: Option<String>,
    min_port: u16,
    max_port: u16,
    bind_tunnels: IpAddr,
    allocated: AsyncMutex<HashMap<u16, ()>>,
    pending: AsyncMutex<HashMap<String, TcpStream>>,
    controls: AsyncMutex<HashMap<u16, tokio::sync::mpsc::Sender<Value>>>,
}

async fn handle_server_connection(mut stream: TcpStream, peer_addr: String, state: Arc<ServerState>) -> Result<()> {
    // For logging, we need to print incoming connection
    print_server_control(&peer_addr, "incoming connection");

    // If secret required, send Challenge
    let mut authenticated = state.secret.is_none();

    if let Some(secret) = &state.secret {
        let challenge = Uuid::new_v4().to_string();
        write_msg(&mut stream, &json!({"Challenge": challenge})).await?;
        // Wait for Authenticate
        let msg = match timeout(Duration::from_secs(3), read_msg(&mut stream)).await {
            Ok(Ok(m)) => m,
            Ok(Err(e)) => {
                print_server_control_warn(&peer_addr, &format!("server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", e));
                print_server_control(&peer_addr, "connection exited");
                return Ok(());
            }
            Err(_) => {
                print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mserver requires secret, but no secret was provided");
                // Send Error?
                let _ = write_msg(&mut stream, &json!({"Error": "server requires secret, but no secret was provided"})).await;
                print_server_control(&peer_addr, "connection exited");
                return Ok(());
            }
        };
        if let Some(auth) = msg.get("Authenticate").and_then(|v| v.as_str()) {
            let expected = compute_auth(secret, &challenge);
            if auth != expected {
                print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0minvalid secret");
                let _ = write_msg(&mut stream, &json!({"Error": "invalid secret"})).await;
                print_server_control(&peer_addr, "connection exited");
                return Ok(());
            } else {
                authenticated = true;
            }
        } else if let Some(hello) = msg.get("Hello") {
            // Client sent Hello without auth
            print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mserver requires secret, but no secret was provided");
            let _ = write_msg(&mut stream, &json!({"Error": "server requires secret, but no secret was provided"})).await;
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        } else {
            print_server_control_warn(&peer_addr, &format!("server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", "invalid auth"));
            let _ = write_msg(&mut stream, &json!({"Error": "invalid secret"})).await;
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
    }

    // Now wait for Hello or Accept
    let msg = match timeout(Duration::from_secs(3), read_msg(&mut stream)).await {
        Ok(Ok(m)) => m,
        Ok(Err(e)) => {
            if !authenticated {
                print_server_control_warn(&peer_addr, &format!("server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", e));
            } else {
                print_server_control(&peer_addr, "connection exited");
            }
            return Ok(());
        }
        Err(_) => {
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
    };

    if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
        let requested = hello_port as u16;
        // Validate port range
        if requested != 0 && (requested < state.min_port || requested > state.max_port) {
            let _ = write_msg(&mut stream, &json!({"Error": "client port number not in allowed range"})).await;
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
        // Allocate port
        let allocated = if requested == 0 {
            allocate_random_port(&state).await
        } else {
            // Try to bind requested
            let bind_addr = state.bind_tunnels;
            match TcpListener::bind((bind_addr, requested)).await {
                Ok(listener) => {
                    // Check if already allocated
                    let mut alloc = state.allocated.lock().await;
                    if alloc.contains_key(&requested) {
                        None
                    } else {
                        alloc.insert(requested, ());
                        // Need to keep listener alive; we will spawn task for it
                        // But we need to store listener
                        // For now, we will drop listener? We need to keep it.
                        // Instead, we should create listener and keep it in state.
                        // Let's handle differently: allocation should try to bind and if success, keep listener.
                        Some((requested, listener))
                    }
                }
                Err(_) => None,
            }
        };

        match allocated {
            Some((port, listener)) => {
                // For random allocation case, need to handle
                // Actually for random, allocate_random_port returns Option<(port, listener)>
                // For requested, we have listener
                // Send Hello response
                write_msg(&mut stream, &json!({"Hello": port})).await?;
                // Send Heartbeat
                write_msg(&mut stream, &Value::String("Heartbeat".to_string())).await?;
                print_server_control(&peer_addr, &format!("new client \x1b[3mhost\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", state.bind_tunnels, port));
                // Keep control connection and spawn external accept loop
                // Need to store control sender for later Connection notifications
                // For simplicity, we will hold the stream and use it to send Connection messages
                // But we need to be able to write to it from external accept tasks.
                // We can split stream into read/write halves and use an mpsc channel to send messages to control.
                // Simpler: we can keep the stream as is and in this task, handle both reading from control (for heartbeat) and writing Connection notifications via external tasks using a shared sender.
                // Instead, we can create a channel and spawn a writer task.

                // Create channel for control messages
                let (tx, mut rx) = tokio::sync::mpsc::channel::<Value>(100);
                // Store tx for this port's control
                {
                    let mut controls = state.controls.lock().await;
                    controls.insert(port, tx.clone());
                }
                // Spawn task to handle external connections for this port
                let state_clone = state.clone();
                let peer_clone = peer_addr.clone();
                tokio::spawn(async move {
                    loop {
                        match listener.accept().await {
                            Ok((ext_stream, ext_addr)) => {
                                print_server_control(&peer_clone, &format!("new connection \x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", ext_addr, port));
                                let conn_id = Uuid::new_v4().to_string();
                                // Store pending
                                {
                                    let mut pending = state_clone.pending.lock().await;
                                    pending.insert(conn_id.clone(), ext_stream);
                                }
                                // Send Connection to control
                                let msg = json!({"Connection": conn_id});
                                if tx.send(msg).await.is_err() {
                                    // Control closed
                                    break;
                                }
                            }
                            Err(e) => {
                                // Listener error
                                break;
                            }
                        }
                    }
                });

                // Now handle control connection: need to forward messages from rx to stream, and also read from stream (for heartbeat or close)
                // Use select
                let mut control_stream = stream;
                loop {
                    tokio::select! {
                        msg = rx.recv() => {
                            match msg {
                                Some(m) => {
                                    if let Err(e) = write_msg(&mut control_stream, &m).await {
                                        print_server_control(&peer_addr, "connection exited");
                                        break;
                                    }
                                }
                                None => {
                                    print_server_control(&peer_addr, "connection exited");
                                    break;
                                }
                            }
                        }
                        res = read_msg(&mut control_stream) => {
                            match res {
                                Ok(m) => {
                                    if m.is_string() && m.as_str() == Some("Heartbeat") {
                                        // Respond with Heartbeat?
                                        let _ = write_msg(&mut control_stream, &Value::String("Heartbeat".to_string())).await;
                                    } else {
                                        // Unknown, ignore
                                    }
                                }
                                Err(e) => {
                                    // EOF or error
                                    print_server_control(&peer_addr, "connection exited");
                                    break;
                                }
                            }
                        }
                    }
                }
                // Cleanup allocated port
                {
                    let mut alloc = state.allocated.lock().await;
                    alloc.remove(&port);
                }
                {
                    let mut controls = state.controls.lock().await;
                    controls.remove(&port);
                }
            }
            None => {
                let _ = write_msg(&mut stream, &json!({"Error": "failed to find an available port"})).await;
                print_server_control(&peer_addr, "connection exited");
            }
        }
    } else if let Some(accept_id) = msg.get("Accept").and_then(|v| v.as_str()) {
        // Proxy connection
        let accept_id = accept_id.to_string();
        print_server_control(&peer_addr, &format!("incoming connection"));
        // Need to find pending external
        let ext_stream = {
            let mut pending = state.pending.lock().await;
            pending.remove(&accept_id)
        };
        if let Some(mut ext_stream) = ext_stream {
            print_server_control(&peer_addr, &format!("forwarding connection \x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}", accept_id));
            // Now forward between ext_stream and proxy stream
            let mut proxy_stream = stream;
            // Need to handle forwarding; if secret, proxy already authenticated, so just copy
            let _ = tokio::io::copy_bidirectional(&mut ext_stream, &mut proxy_stream).await;
            print_server_control_warn(&peer_addr, &format!("connection exited with error \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mConnection reset by peer (os error 104)"));
        } else {
            // No pending, close
            print_server_control(&peer_addr, "connection exited");
        }
    } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
        print_server_control_warn(&peer_addr, &format!("server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0m{}", err));
        print_server_control(&peer_addr, "connection exited");
    } else {
        print_server_control(&peer_addr, "connection exited");
    }

    Ok(())
}

async fn allocate_random_port(state: &Arc<ServerState>) -> Option<(u16, TcpListener)> {
    use rand::seq::SliceRandom;
    let mut rng = rand::thread_rng();
    let mut ports: Vec<u16> = (state.min_port..=state.max_port).collect();
    ports.shuffle(&mut rng);
    for port in ports {
        // Check not already allocated
        {
            let alloc = state.allocated.lock().await;
            if alloc.contains_key(&port) {
                continue;
            }
        }
        let bind_addr = state.bind_tunnels;
        if let Ok(listener) = TcpListener::bind((bind_addr, port)).await {
            let mut alloc = state.allocated.lock().await;
            // double check after bind
            if alloc.contains_key(&port) {
                continue;
            }
            alloc.insert(port, ());
            return Some((port, listener));
        }
    }
    None
}
