fn write_msg(stream: &mut TcpStream, value: &Value) -> Result<()> {
    let s = serde_json::to_string(value).unwrap();
    stream.write_all(s.as_bytes())?;
    stream.write_all(b"\x00")?;
    stream.flush()?;
    Ok(())
}

fn read_msg(stream: &mut TcpStream) -> Result<Value> {
    let mut buf = Vec::new();
    let mut byte = [0u8; 1];
    loop {
        let n = stream.read(&mut byte)?;
        if n == 0 {
            return Err(anyhow!("unexpected EOF"));
        }
        if byte[0] == 0 {
            break;
        }
        buf.push(byte[0]);
        if buf.len() > 8192 {
            return Err(anyhow!("frame error, invalid byte length"));
        }
    }
    if buf.is_empty() {
        return Err(anyhow!("unexpected EOF"));
    }
    let s = String::from_utf8(buf).context("invalid utf8")?;
    let v: Value = serde_json::from_str(&s).context("unable to parse message")?;
    Ok(v)
}

fn read_msg_timeout(stream: &mut TcpStream, dur: Duration) -> Result<Value> {
    stream.set_read_timeout(Some(dur))?;
    let res = read_msg(stream);
    stream.set_read_timeout(None)?;
    res
}

fn compute_auth(secret: &str, challenge: &str) -> String {
    let key = Sha256::digest(secret.as_bytes());
    let uuid = Uuid::parse_str(challenge).unwrap();
    let block_size = 64;
    let mut key_block = [0u8; 64];
    if key.len() > block_size {
        let hashed = Sha256::digest(&key);
        key_block[..32].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(&key);
    }
    let mut ipad = [0x36u8; 64];
    let mut opad = [0x5cu8; 64];
    for i in 0..64 {
        ipad[i] ^= key_block[i];
        opad[i] ^= key_block[i];
    }
    let mut inner = Sha256::new();
    inner.update(&ipad);
    inner.update(uuid.as_bytes());
    let inner_hash = inner.finalize();
    let mut outer = Sha256::new();
    outer.update(&opad);
    outer.update(inner_hash);
    let result = outer.finalize();
    hex::encode(result)
}

fn run_local(matches: &clap::ArgMatches) -> Result<()> {
    let local_port: u16 = *matches.get_one::<u16>("LOCAL_PORT").unwrap();
    let local_host: String = matches.get_one::<String>("local-host").unwrap().clone();
    let to: String = matches.get_one::<String>("to").unwrap().clone();
    let port: u16 = *matches.get_one::<u16>("port").unwrap();
    let secret: Option<String> = matches.get_one::<String>("secret").cloned();

    let server_addr = format!("{}:7835", to);
    let mut stream = match TcpStream::connect(&server_addr) {
        Ok(s) => s,
        Err(e) => {
            return Err(anyhow!(e).context(format!("could not connect to {}", server_addr)));
        }
    };
    stream.set_read_timeout(Some(Duration::from_secs(5)))?;
    stream.set_write_timeout(Some(Duration::from_secs(5)))?;

    if let Some(secret) = &secret {
        let msg = read_msg_timeout(&mut stream, Duration::from_secs(3))
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?;
        if let Some(challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            let auth = compute_auth(secret, challenge);
            write_msg(&mut stream, &json!({"Authenticate": auth}))?;
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            return Err(anyhow!("server error: {}", err));
        } else {
            return Err(anyhow!("expected authentication challenge, but no secret was required"));
        }
        write_msg(&mut stream, &json!({"Hello": port}))?;
        let msg = read_msg_timeout(&mut stream, Duration::from_secs(3))
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?;
        if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            return Err(anyhow!("server error: {}", err));
        } else if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
            let allocated = hello_port as u16;
            print_client_connected(allocated);
            print_client_listening(&to, allocated);
            let _ = read_msg_timeout(&mut stream, Duration::from_millis(200));
            return handle_client_control(stream, local_host, local_port, to, Some(secret.clone()));
        } else {
            return Err(anyhow!("unexpected message: {:?}", msg));
        }
    } else {
        write_msg(&mut stream, &json!({"Hello": port}))?;
        let msg = read_msg_timeout(&mut stream, Duration::from_secs(3))
            .map_err(|_| anyhow!("timed out waiting for initial message\n\nCaused by:\n    deadline has elapsed"))?;
        if let Some(_challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            return Err(anyhow!("server requires authentication, but no client secret was provided"));
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            return Err(anyhow!("server error: {}", err));
        } else if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
            let allocated = hello_port as u16;
            print_client_connected(allocated);
            print_client_listening(&to, allocated);
            let _ = read_msg_timeout(&mut stream, Duration::from_millis(200));
            return handle_client_control(stream, local_host, local_port, to, None);
        } else {
            return Err(anyhow!("unexpected message: {:?}", msg));
        }
    }
}

fn handle_client_control(mut control: TcpStream, local_host: String, local_port: u16, to: String, secret: Option<String>) -> Result<()> {
    control.set_read_timeout(Some(Duration::from_secs(600)))?;
    loop {
        let msg = match read_msg(&mut control) {
            Ok(m) => m,
            Err(e) => {
                if e.to_string().contains("unexpected EOF") {
                    return Ok(());
                }
                return Err(anyhow!(e).context("frame error, invalid byte length"));
            }
        };
        if let Some(conn_id) = msg.get("Connection").and_then(|v| v.as_str()) {
            let conn_id = conn_id.to_string();
            let lh = local_host.clone();
            let t = to.clone();
            let s = secret.clone();
            thread::spawn(move || {
                let _ = handle_proxy(conn_id.clone(), lh, local_port, t, s);
            });
        } else if msg.is_string() && msg.as_str() == Some("Heartbeat") {
            let _ = write_msg(&mut control, &Value::String("Heartbeat".to_string()));
        } else if let Some(err) = msg.get("Error").and_then(|v| v.as_str()) {
            return Err(anyhow!("server error: {}", err));
        }
    }
}

fn handle_proxy(conn_id: String, local_host: String, local_port: u16, to: String, secret: Option<String>) -> Result<()> {
    print_proxy_new_connection(&conn_id);
    let server_addr = format!("{}:7835", to);
    let mut stream = match TcpStream::connect(&server_addr) {
        Ok(s) => s,
        Err(e) => {
            print_proxy_exited(&conn_id);
            return Err(anyhow!(e).context(format!("could not connect to {}", server_addr)));
        }
    };
    stream.set_read_timeout(Some(Duration::from_secs(5)))?;
    stream.set_write_timeout(Some(Duration::from_secs(5)))?;
    if let Some(secret) = &secret {
        let msg = read_msg_timeout(&mut stream, Duration::from_secs(3))
            .map_err(|_| anyhow!("timed out waiting for initial message"))?;
        if let Some(challenge) = msg.get("Challenge").and_then(|v| v.as_str()) {
            let auth = compute_auth(secret, challenge);
            write_msg(&mut stream, &json!({"Authenticate": auth}))?;
        } else {
            print_proxy_exited(&conn_id);
            return Err(anyhow!("expected challenge"));
        }
    }
    write_msg(&mut stream, &json!({"Accept": conn_id.clone()}))?;
    let local_addr = format!("{}:{}", local_host, local_port);
    let mut local_stream = match TcpStream::connect(&local_addr) {
        Ok(s) => s,
        Err(e) => {
            print_proxy_exited(&conn_id);
            return Err(anyhow!(e).context(format!("could not connect to local {}", local_addr)));
        }
    };
    let mut stream_clone = stream.try_clone()?;
    let mut local_clone = local_stream.try_clone()?;
    let handle1 = thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match stream_clone.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => { if local_clone.write_all(&buf[..n]).is_err() { break; } }
                Err(_) => break,
            }
        }
    });
    let handle2 = thread::spawn(move || {
        let mut buf = [0u8; 8192];
        loop {
            match local_stream.read(&mut buf) {
                Ok(0) => break,
                Ok(n) => { if stream.write_all(&buf[..n]).is_err() { break; } }
                Err(_) => break,
            }
        }
    });
    let _ = handle1.join();
    let _ = handle2.join();
    print_proxy_exited(&conn_id);
    Ok(())
}

fn run_server(matches: &clap::ArgMatches) -> Result<()> {
    let min_port: u16 = *matches.get_one::<u16>("min-port").unwrap();
    let max_port: u16 = *matches.get_one::<u16>("max-port").unwrap();
    let secret: Option<String> = matches.get_one::<String>("secret").cloned();
    let bind_addr_str: String = matches.get_one::<String>("bind-addr").unwrap().clone();
    let bind_addr: IpAddr = bind_addr_str.parse().map_err(|_| anyhow!("invalid IP address syntax"))?;
    let bind_tunnels_str: Option<String> = matches.get_one::<String>("bind-tunnels").cloned();
    let bind_tunnels: IpAddr = if let Some(s) = bind_tunnels_str {
        s.parse().map_err(|_| anyhow!("invalid IP address syntax"))?
    } else {
        bind_addr
    };

    if min_port > max_port {
        return Err(anyhow!("port range is empty"));
    }

    let listener = TcpListener::bind((bind_addr, 7835)).map_err(|e| anyhow!(e))?;
    print_server_listening(&bind_addr_str);

    let state = Arc::new(ServerState {
        secret: secret.clone(),
        min_port,
        max_port,
        bind_tunnels,
        bind_tunnels_str: bind_tunnels.to_string(),
        allocated: Mutex::new(HashMap::new()),
        pending: Mutex::new(HashMap::new()),
    });

    for stream in listener.incoming() {
        match stream {
            Ok(socket) => {
                let peer = socket.peer_addr().map(|a| a.to_string()).unwrap_or_else(|_| "unknown".to_string());
                let state = state.clone();
                thread::spawn(move || {
                    let _ = handle_server_connection(socket, peer, state);
                });
            }
            Err(e) => {
                eprintln!("accept error: {}", e);
            }
        }
    }
    Ok(())
}

struct ServerState {
    secret: Option<String>,
    min_port: u16,
    max_port: u16,
    bind_tunnels: IpAddr,
    bind_tunnels_str: String,
    allocated: Mutex<HashMap<u16, Arc<TcpListener>>>,
    pending: Mutex<HashMap<String, TcpStream>>,
}

fn handle_server_connection(mut stream: TcpStream, peer_addr: String, state: Arc<ServerState>) -> Result<()> {
    print_server_control(&peer_addr, "incoming connection");
    stream.set_read_timeout(Some(Duration::from_secs(3)))?;
    stream.set_write_timeout(Some(Duration::from_secs(5)))?;

    if let Some(secret) = &state.secret {
        let challenge = Uuid::new_v4().to_string();
        write_msg(&mut stream, &json!({"Challenge": challenge}))?;
        let msg = match read_msg_timeout(&mut stream, Duration::from_secs(3)) {
            Ok(m) => m,
            Err(e) => {
                print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mserver requires secret, but no secret was provided");
                let _ = write_msg(&mut stream, &json!({"Error": "server requires secret, but no secret was provided"}));
                print_server_control(&peer_addr, "connection exited");
                return Ok(());
            }
        };
        if let Some(auth) = msg.get("Authenticate").and_then(|v| v.as_str()) {
            let expected = compute_auth(secret, &challenge);
            if auth != expected {
                print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0minvalid secret");
                let _ = write_msg(&mut stream, &json!({"Error": "invalid secret"}));
                print_server_control(&peer_addr, "connection exited");
                return Ok(());
            }
        } else if msg.get("Hello").is_some() {
            print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mserver requires secret, but no secret was provided");
            let _ = write_msg(&mut stream, &json!({"Error": "server requires secret, but no secret was provided"}));
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        } else {
            print_server_control_warn(&peer_addr, "server handshake failed \x1b[3merr\x1b[0m\x1b[2m=\x1b[0minvalid secret");
            let _ = write_msg(&mut stream, &json!({"Error": "invalid secret"}));
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
    }

    let msg = match read_msg_timeout(&mut stream, Duration::from_secs(3)) {
        Ok(m) => m,
        Err(_) => {
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
    };

    if let Some(hello_port) = msg.get("Hello").and_then(|v| v.as_u64()) {
        let requested = hello_port as u16;
        if requested != 0 && (requested < state.min_port || requested > state.max_port) {
            let _ = write_msg(&mut stream, &json!({"Error": "client port number not in allowed range"}));
            print_server_control(&peer_addr, "connection exited");
            return Ok(());
        }
        let allocated = if requested == 0 {
            allocate_random_port(&state)
        } else {
            let bind_addr = state.bind_tunnels;
            match TcpListener::bind((bind_addr, requested)) {
                Ok(listener) => {
                    let mut alloc = state.allocated.lock().unwrap();
                    if alloc.contains_key(&requested) {
                        None
                    } else {
                        let arc = Arc::new(listener);
                        alloc.insert(requested, arc.clone());
                        Some((requested, arc))
                    }
                }
                Err(_) => None,
            }
        };
        match allocated {
            Some((port, listener)) => {
                write_msg(&mut stream, &json!({"Hello": port}))?;
                write_msg(&mut stream, &Value::String("Heartbeat".to_string()))?;
                print_server_control(&peer_addr, &format!("new client \x1b[3mhost\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", state.bind_tunnels_str, port));
                let (tx, rx) = mpsc::channel::<Value>();
                let state_clone = state.clone();
                let peer_clone = peer_addr.clone();
                thread::spawn(move || {
                    loop {
                        match listener.accept() {
                            Ok((ext_stream, ext_addr)) => {
                                print_server_control(&peer_clone, &format!("new connection \x1b[3maddr\x1b[0m\x1b[2m=\x1b[0m{} \x1b[3mport\x1b[0m\x1b[2m=\x1b[0m{}", ext_addr, port));
                                let conn_id = Uuid::new_v4().to_string();
                                {
                                    let mut pending = state_clone.pending.lock().unwrap();
                                    pending.insert(conn_id.clone(), ext_stream);
                                }
                                let msg = json!({"Connection": conn_id});
                                if tx.send(msg).is_err() {
                                    break;
                                }
                            }
                            Err(_) => break,
                        }
                    }
                });
                stream.set_read_timeout(Some(Duration::from_millis(200)))?;
                loop {
                    match rx.try_recv() {
                        Ok(m) => {
                            if let Err(_) = write_msg(&mut stream, &m) {
                                print_server_control(&peer_addr, "connection exited");
                                break;
                            }
                        }
                        Err(mpsc::TryRecvError::Empty) => {},
                        Err(mpsc::TryRecvError::Disconnected) => {
                            print_server_control(&peer_addr, "connection exited");
                            break;
                        }
                    }
                    match read_msg(&mut stream) {
                        Ok(m) => {
                            if m.is_string() && m.as_str() == Some("Heartbeat") {
                                let _ = write_msg(&mut stream, &Value::String("Heartbeat".to_string()));
                            }
                        }
                        Err(e) => {
                            if e.to_string().contains("WouldBlock") || e.to_string().contains("timed out") || e.to_string().contains("Resource temporarily unavailable") {
                            } else if e.to_string().contains("unexpected EOF") {
                                print_server_control(&peer_addr, "connection exited");
                                break;
                            }
                        }
                    }
                    thread::sleep(Duration::from_millis(50));
                }
                {
                    let mut alloc = state.allocated.lock().unwrap();
                    alloc.remove(&port);
                }
            }
            None => {
                let _ = write_msg(&mut stream, &json!({"Error": "failed to find an available port"}));
                print_server_control(&peer_addr, "connection exited");
            }
        }
    } else if let Some(accept_id) = msg.get("Accept").and_then(|v| v.as_str()) {
        let accept_id = accept_id.to_string();
        print_server_control(&peer_addr, "incoming connection");
        let ext_stream = {
            let mut pending = state.pending.lock().unwrap();
            pending.remove(&accept_id)
        };
        if let Some(mut ext_stream) = ext_stream {
            print_server_control(&peer_addr, &format!("forwarding connection \x1b[3mid\x1b[0m\x1b[2m=\x1b[0m{}", accept_id));
            let mut proxy_stream = stream;
            proxy_stream.set_read_timeout(None).ok();
            proxy_stream.set_write_timeout(None).ok();
            ext_stream.set_read_timeout(None).ok();
            ext_stream.set_write_timeout(None).ok();
            let mut proxy_clone = proxy_stream.try_clone().unwrap();
            let mut ext_clone = ext_stream.try_clone().unwrap();
            let h1 = thread::spawn(move || {
                let mut buf = [0u8; 8192];
                loop {
                    match proxy_clone.read(&mut buf) {
                        Ok(0) => break,
                        Ok(n) => { if ext_clone.write_all(&buf[..n]).is_err() { break; } }
                        Err(_) => break,
                    }
                }
            });
            let h2 = thread::spawn(move || {
                let mut buf = [0u8; 8192];
                loop {
                    match ext_stream.read(&mut buf) {
                        Ok(0) => break,
                        Ok(n) => { if proxy_stream.write_all(&buf[..n]).is_err() { break; } }
                        Err(_) => break,
                    }
                }
            });
            let _ = h1.join();
            let _ = h2.join();
            print_server_control_warn(&peer_addr, "connection exited with error \x1b[3merr\x1b[0m\x1b[2m=\x1b[0mConnection reset by peer (os error 104)");
        } else {
            print_server_control(&peer_addr, "connection exited");
        }
    } else {
        print_server_control(&peer_addr, "connection exited");
    }
    Ok(())
}

fn allocate_random_port(state: &Arc<ServerState>) -> Option<(u16, Arc<TcpListener>)> {
    use rand::seq::SliceRandom;
    let mut rng = rand::thread_rng();
    let mut ports: Vec<u16> = (state.min_port..=state.max_port).collect();
    ports.shuffle(&mut rng);
    for port in ports {
        {
            let alloc = state.allocated.lock().unwrap();
            if alloc.contains_key(&port) {
                continue;
            }
        }
        let bind_addr = state.bind_tunnels;
        if let Ok(listener) = TcpListener::bind((bind_addr, port)) {
            let mut alloc = state.allocated.lock().unwrap();
            if alloc.contains_key(&port) {
                continue;
            }
            let arc = Arc::new(listener);
            alloc.insert(port, arc.clone());
            return Some((port, arc));
        }
    }
    None
}
