# The write_msg does two writes: one for JSON, one for \x00, and flush. That could be two packets.
# To make it atomic, we should do a single write of JSON + \x00.

cat > /tmp/fix_write.py << 'PY'
import pathlib
p=pathlib.Path("src/main.rs")
t=p.read_text()
old="""fn write_msg(stream: &mut TcpStream, value: &Value) -> Result<()> {
    let s = serde_json::to_string(value).unwrap();
    stream.write_all(s.as_bytes())?;
    stream.write_all(b"\\x00")?;
    stream.flush()?;
    Ok(())
}"""
new="""fn write_msg(stream: &mut TcpStream, value: &Value) -> Result<()> {
    let mut buf = serde_json::to_vec(value).unwrap();
    buf.push(0);
    stream.write_all(&buf)?;
    stream.flush()?;
    Ok(())
}"""
if old in t:
    t=t.replace(old, new)
    p.write_text(t)
    print("fixed write_msg")
else:
    print("not found")
